def applyOperations(nums):
    a = list(nums)
    n = len(a)
    for i in range(n - 1):
        if a[i] == a[i + 1]:
            a[i] *= 2
            a[i + 1] = 0
    write = 0
    for read in range(n):
        if a[read] != 0:
            a[write] = a[read]
            write += 1
    for k in range(write, n):
        a[k] = 0
    return a
